import {chinaDate} from './cloud-contract.mjs';
import {signedCostMoney} from './cost-sources-contract.mjs';
import {hasSensitive} from './admin-permissions.mjs';
import {reviewSourceLink} from './finance-month-review-view.mjs';
export function createFinanceClosingViews({api,h,showPanel,getUser,writable,notify,localTime}){
 const head=t=>`<div class="dialog-header"><h2>${h(t)}</h2><button class="icon-button" data-finance-closing-close aria-label="关闭财务月结">×</button></div>`;
 const maintain=()=>writable&&hasSensitive(getUser(),'finance');
 const amount=v=>v===null?'尚无完整利润依据':h(signedCostMoney(v));
 function snapshot(s){const o=s.overview;return `<section class="summary-strip"><div><b>${amount(o.summary.incomeCents)}</b><span>平台可提现收入</span></div><div><b>${amount(o.summary.storeProfitCents)}</b><span>店铺利润合计</span></div><div><b>${amount(o.publicCents)}</b><span>公共运营费用</span></div><div><b>${amount(o.summary.studioProfitCents)}</b><span>工作室利润</span></div></section><p>本月确认经营店铺：${s.scope?(s.scope.stores.map(r=>h(r.name)).join('、')||'已确认无经营店铺'):'尚未确认'}。</p><p>经营依据待补 ${s.counts.blocker} 项 · 资金与报销提示 ${s.counts.review} 项。</p><p class="muted">收入按平台可提现金额确认，已扣佣金与客户退款；商品、代发及工作室成本另算，公共费用扣一次。资金和报销只保留检查时已录来源，后续仍可继续处理，不作为银行余额或所选月末报销余额。</p>`;}
 async function state(month=chinaDate().slice(0,7),offset=0){await showPanel('财务月结',async signal=>{const s=await api.financeClosing(month,offset,signal),locked=s.record?.action==='lock',data=locked?s.record.snapshot:s.candidate.snapshot;return head(month+' · 财务月结')+`<div class="action-row"><label>经营月份<input type="month" min="1900-01" max="2199-12" value="${h(month)}" data-finance-closing-month></label><button class="text-button" data-finance-review="${h(month)}">月度来源检查</button><button class="text-button" data-studio-overview="${h(month)}">经营总览</button></div><p class="planning-rule">${locked?'本月已锁定，以下为锁定时的结果与依据。更正历史前请先重新开放。':s.record?'本月已重新开放，以下为当前来源；再次锁定前需重新核对。':'本月尚未锁定，以下为当前来源预览。'}</p>${snapshot(data)}${maintain()?`<button class="primary" data-finance-closing-edit="${h(month)}" ${!locked&&!s.candidate.ready?'disabled':''}>${locked?'重新开放本月':'核对并锁定本月'}</button>`:''}${!locked&&!s.candidate.ready?'<p class="save-error">请先完成月份、经营店铺、收入及成本依据检查。</p>':''}<h3>月结与重新开放历史 · ${s.history.total} 条</h3>${s.history.rows.map(r=>`<article class="observation"><button class="text-button" data-finance-closing-detail="${h(r.id)}">第 ${r.version} 版 · ${r.action==='lock'?'已锁定':'已重新开放'}</button><p class="preserve-text">${h(r.reason)}</p><small>${h(r.actor)} · ${h(localTime(r.createdAt))}</small></article>`).join('')||'<p class="muted">尚无月结记录。</p>'}<div class="pager"><button class="secondary" data-finance-closing="${h(month)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><button class="secondary" data-finance-closing="${h(month)}" data-offset="${offset+50}" ${offset+50>=s.history.total?'disabled':''}>下一页</button></div>`;});}
 async function detail(id,offset=0){await showPanel('历史月结快照',async signal=>{const r=await api.financeClosingRecord(id,signal),s=r.snapshot;return head(r.month+' · 第 '+r.version+' 版'+(r.action==='lock'?'锁定快照':'重新开放记录'))+`<button class="text-button" data-finance-closing="${h(r.month)}">返回本月状态</button><p>${h(r.actor)} · ${h(localTime(r.createdAt))}</p><p class="preserve-text">${h(r.reason)}</p><p class="muted">历史记录保留当次锁定来源；重新开放不改写原快照。</p>${snapshot(s)}<details><summary>原始来源规模</summary><p>支出 ${s.sources.expenses.length} 笔 · 库存成本流水 ${s.inventory.length} 条 · 样品成本来源 ${s.sampleSources.length} 条 · 手工资金记录 ${s.cash.length} 笔 · 原报销付款 ${s.reimbursements.length} 笔。完整依据保存在本次快照，以下入口查看原记录当前详情。</p></details>${s.issues.slice(offset,offset+50).map(p=>`<article class="observation"><p>${h(p.label)}${p.amountCents!==undefined?' · '+h(signedCostMoney(p.amountCents)):''}</p>${reviewSourceLink(p,r.month,h,hasSensitive(getUser(),'resources'))}</article>`).join('')}<div class="pager"><button class="secondary" data-finance-closing-detail="${h(id)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页提示</button><span>${s.issues.length} 项原提示</span><button class="secondary" data-finance-closing-detail="${h(id)}" data-offset="${offset+50}" ${offset+50>=s.issues.length?'disabled':''}>下一页提示</button></div>`;});}
 document.addEventListener('click',e=>{if(e.target.closest('[data-finance-closing-close]'))document.querySelector('#cloud-detail').close();const b=e.target.closest('[data-finance-closing]'),d=e.target.closest('[data-finance-closing-detail]');if(b)state(b.dataset.financeClosing||document.querySelector('#finance-month')?.value||chinaDate().slice(0,7),Number(b.dataset.offset||0)).catch(e=>notify(e.message));if(d)detail(d.dataset.financeClosingDetail,Number(d.dataset.offset||0)).catch(e=>notify(e.message));});
 document.addEventListener('change',e=>{if(e.target.matches('[data-finance-closing-month]'))state(e.target.value).catch(e=>notify(e.message));});return {state,detail};
}
